ST.xhtml:p:
Rtring_AxisStop(CLK :=g_bAxisStopFlag);
IF Rtring_AxisStop.Q THEN
  IF g_nAxisStopP = 14 THEN
      nRelState5 := 100;
      g_bAxisStopFlag := FALSE;
  END_IF;
END_IF;

Rtring_AxisStop1(CLK :=g_bAxisStopFlag_14);
IF Rtring_AxisStop1.Q THEN
  nRelState5 := 100;
  g_bAxisStopFlag_14 := FALSE;
END_IF;

(*防甩轴4*)
RelRtring4(CLK :=g_bAnRejection4RelEnable OR g_biAnRejection4RelEnable OR bAnRejection4RelEnable);
IF RelRtring4.Q THEN
  nRelState4 :=1;
  g_bAnRejection4RelDone := FALSE;
  g_boAnRejection4RelDone := FALSE;
  bAnRejection4RelDone := FALSE;
  IF g_biAnRejection4RelEnable THEN
    dARTargetPos4 := AntiRejection4.NCTOPLC.ActPos + g_fiARRelDis4;
    dARTargetVel4 := g_fiARRelVel4;
  ELSIF g_bAnRejection4RelEnable THEN
    dARTargetPos4 := AntiRejection4.NCTOPLC.ActPos + g_fARRelDis4;
    dARTargetVel4 := g_fARRelVel4;
    g_bAnRejection1RelEnable := FALSE;
  ELSE
      dARTargetPos4 := AntiRejection4.NCTOPLC.ActPos + dARRelDis4;
      IF g_bFastInch=0 THEN
        dARTargetVel4 := dAntiRejection4SlowVel;
      ELSE
        dARTargetVel4 := dAntiRejection4FastVel;
      END_IF;
      bAnRejection4RelEnable := FALSE; 
  END_IF;
  IF dARTargetVel4 = 0.0 THEN
    dARTargetVel4 := dAntiRejection4RelVelocity;
  END_IF;
END_IF;
IF NOT (g_bAnRejection4RelEnable OR g_biAnRejection4RelEnable OR bAnRejection4RelEnable) THEN
  g_bAnRejection4RelDone := FALSE;
  g_boAnRejection4RelDone := FALSE;
  bAnRejection4RelDone := FALSE;
END_IF;

CASE nRelState4 OF
  0:
  nRelState4 := 0;
  1:
  g_AntiRejection4Rel.Execute := TRUE;
  g_AntiRejection4Rel.Velocity := dARTargetVel4;
  g_AntiRejection4Rel.Distance := dARTargetPos4 - AntiRejection4.NCTOPLC.ACTPOS;
  IF g_AntiRejection4Rel.Done THEN
    g_AntiRejection4Rel.Execute := FALSE;
    bAnRejection4RelDone := TRUE;
    g_bAnRejection4RelDone :=TRUE;
    g_boAnRejection4RelDone := TRUE;
    nRelState4 := 0;
    g_bFinishedM316_1 := FALSE;
  END_IF;
  IF g_bPlcPauseBuffer THEN
    nRelState4 := 20;
  END_IF;
  IF g_AntiRejection4Rel.CommandAborted OR g_AntiRejection4Rel.Error THEN
    g_AntiRejection4Rel.Execute := FALSE;
    nRelState4 := 0;
  END_IF;
  20:
  g_AntiRejection4Rel.Execute := FALSE;
  g_AntiRejection4Stop.Execute := TRUE;
  IF g_AntiRejection4Stop.Done AND g_bPlcStartBuffer THEN
    g_AntiRejection4Stop.Execute := FALSE;
    nRelState4 := 1;
  END_IF;
  IF g_AntiRejection4Stop.CommandAborted OR g_AntiRejection4Stop.Error THEN 
    g_AntiRejection4Stop.Execute := FALSE;
    nRelState4 := 0;
  END_IF;
END_CASE;
IF g_bPlcResetBuffer THEN
  nRelState4 := 0;
  g_AntiRejection4Rel.Execute := FALSE;
  g_AntiRejection4Stop.Execute := FALSE;
END_IF;
(*防甩轴5*)
RelRtring5(CLK :=g_bAnRejection5RelEnable OR g_biAnRejection5RelEnable OR bAnRejection5RelEnable OR g_bMiddleMoveAxisRelEnableM);
IF RelRtring5.Q THEN
  nRelState5 :=1;
  g_bAnRejection5RelDone := FALSE;
  g_boAnRejection5RelDone := FALSE;
  bAnRejection5RelDone := FALSE;
  g_bMiddleMoveAxisDone := FALSE;
  IF g_biAnRejection5RelEnable THEN
    dARTargetPos5 := AntiRejection5.NCTOPLC.ActPos + g_fiARRelDis5;
    dARTargetVel5 := g_fiARRelVel5;
  ELSIF g_bAnRejection1RelEnable THEN
    dARTargetPos5 := AntiRejection5.NCTOPLC.ActPos + g_fARRelDis5;
    dARTargetVel5 := g_fARRelVel5;
    g_bAnRejection5RelEnable := FALSE;
  ELSIF g_bMiddleMoveAxisRelEnableM THEN
    dARTargetPos5 := AntiRejection5.NCTOPLC.ActPos + g_fARRelDis5;
    dARTargetVel5 := g_dMiddleMoveAxisRelVel;
    g_bMiddleMoveAxisRelEnableM := FALSE;
  ELSE
      dARTargetPos5 := AntiRejection5.NCTOPLC.ActPos + dARRelDis5;
      IF g_bFastInch=0 THEN
        dARTargetVel5 := dAntiRejection5SlowVel;
      ELSE
        dARTargetVel5 := dAntiRejection5FastVel;
      END_IF;
      bAnRejection5RelEnable := FALSE; 
  END_IF;
  IF g_bSetAuxiliaryAxisSpeed THEN
      dARTargetVel5 := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
  END_IF;
  IF dARTargetVel5 = 0.0 THEN
    dARTargetVel5 := dAntiRejection5RelVelocity;
  END_IF;
END_IF;
IF NOT (g_bAnRejection5RelEnable OR g_biAnRejection5RelEnable OR bAnRejection5RelEnable) THEN
  g_bAnRejection5RelDone := FALSE;
  g_boAnRejection5RelDone := FALSE;
  bAnRejection5RelDone := FALSE;
END_IF;

CASE nRelState5 OF
  0:
  nRelState5 := 0;
  1:
  g_AntiRejection5Rel.Execute := TRUE;
  g_AntiRejection5Rel.Velocity := dARTargetVel5;
  g_AntiRejection5Rel.Distance := dARTargetPos5 - AntiRejection5.NCTOPLC.ACTPOS;
  IF g_AntiRejection5Rel.Done THEN
    g_AntiRejection5Rel.Execute := FALSE;
    g_bAnRejection5RelDone :=TRUE;
    g_boAnRejection5RelDone := TRUE;
    g_bMiddleMoveAxisDone := TRUE;
    nRelState5 := 0;
    M.ENABLE[316] := 0;
    g_bFinishedM316_2 := FALSE;
  END_IF;
  IF g_bPlcPauseBuffer THEN
    nRelState5 := 20;
  END_IF;
  IF g_AntiRejection5Rel.CommandAborted OR g_AntiRejection5Rel.Error THEN
    g_AntiRejection5Rel.Execute := FALSE;
    nRelState5 := 0;
  END_IF;
  20:
	  g_AntiRejection5Rel.Execute := FALSE;
	  g_AntiRejection5Stop.Execute := TRUE;
	  IF g_AntiRejection5Stop.Done AND g_bPlcStartBuffer THEN
		g_AntiRejection5Stop.Execute := FALSE;
		nRelState5 := 1;
	  END_IF;
	  IF g_AntiRejection5Stop.CommandAborted OR g_AntiRejection5Stop.Error THEN 
		g_AntiRejection5Stop.Execute := FALSE;
		nRelState5 := 0;
	  END_IF;
	100:
		g_AntiRejection5Rel.Execute := FALSE;
		  g_AntiRejection5Stop.Execute := TRUE;
		  IF g_AntiRejection5Stop.Done  THEN
			g_AntiRejection5Stop.Execute := FALSE;
			nRelState5 := 0;
            M.ENABLE[325] := 0;
            g_bMiddleMoveAxisDone := TRUE;
            g_bFinishedM325_14 := FALSE;
		  END_IF;
		  IF g_AntiRejection5Stop.CommandAborted OR g_AntiRejection5Stop.Error THEN 
			g_AntiRejection5Stop.Execute := FALSE;
			nRelState5 := 0;
            M.ENABLE[325] := 0;
            g_bMiddleMoveAxisDone := TRUE;
            g_bFinishedM325_14 := FALSE;
		  END_IF;

END_CASE;
IF g_bPlcResetBuffer THEN
  nRelState5 := 0;
  g_AntiRejection5Rel.Execute := FALSE;
  g_AntiRejection5Stop.Execute := FALSE;
END_IF;
